  <style>
    :root {
      color-scheme: light;
      --bg: #f3f6fb;
      --panel: rgba(255, 255, 255, 0.84);
      --panel-solid: #ffffff;
      --text: #132238;
      --muted: #607087;
      --border: rgba(15, 23, 42, 0.1);
      --shadow: 0 24px 70px rgba(15, 23, 42, 0.14);
      --shadow-soft: 0 14px 34px rgba(15, 23, 42, 0.08);
      --danger: #e11d48;
      --danger-deep: #be123c;
      --danger-soft: rgba(225, 29, 72, 0.1);
      --accent: #2563eb;
      --accent-soft: rgba(37, 99, 235, 0.12);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, rgba(37, 99, 235, 0.16), transparent 32%),
        linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
    }

    button {
      font: inherit;
    }

    .page-shell {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 48px 20px;
    }

    .preview-layout {
      width: min(100%, 1080px);
      display: grid;
      grid-template-columns: minmax(0, 1.6fr) minmax(280px, 0.9fr);
      gap: 28px;
      align-items: stretch;
    }

    .glass-card {
      background: var(--panel);
      border: 1px solid rgba(255, 255, 255, 0.7);
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
      -webkit-backdrop-filter: blur(18px);
    }

    .preview-card {
      border-radius: 28px;
      overflow: hidden;
      display: grid;
      min-height: 660px;
    }

    .image-stage {
      position: relative;
      background:
        linear-gradient(135deg, rgba(15, 23, 42, 0.82), rgba(30, 64, 175, 0.72)),
        url("https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=80") center/cover;
      padding: 24px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      min-height: 440px;
    }

    .image-stage::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, rgba(15, 23, 42, 0.08), rgba(15, 23, 42, 0.45));
    }

    .stage-chip,
    .image-meta {
      position: relative;
      z-index: 1;
    }

    .stage-chip {
      align-self: flex-start;
      padding: 10px 14px;
      border-radius: 999px;
      color: #eff6ff;
      background: rgba(255, 255, 255, 0.14);
      border: 1px solid rgba(255, 255, 255, 0.2);
      font-size: 0.92rem;
      letter-spacing: 0.01em;
    }

    .image-meta h1 {
      margin: 0 0 8px;
      font-size: clamp(2rem, 4vw, 3rem);
      color: #fff;
    }

    .image-meta p {
      margin: 0;
      color: rgba(255, 255, 255, 0.8);
      max-width: 40ch;
      line-height: 1.6;
    }

    .card-footer {
      background: var(--panel-solid);
      padding: 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      border-top: 1px solid var(--border);
    }

    .asset-details {
      display: grid;
      gap: 10px;
    }

    .asset-details strong {
      font-size: 1.05rem;
    }

    .meta-row {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      color: var(--muted);
      font-size: 0.94rem;
    }

    .meta-pill {
      padding: 8px 12px;
      border-radius: 999px;
      background: #f8fafc;
      border: 1px solid rgba(148, 163, 184, 0.18);
    }

    .sidebar {
      border-radius: 24px;
      padding: 24px;
      display: grid;
      gap: 20px;
      align-content: start;
    }

    .sidebar h2,
    .dialog-copy h2 {
      margin: 0;
      font-size: 1.3rem;
    }

    .sidebar p,
    .dialog-copy p {
      margin: 0;
      color: var(--muted);
      line-height: 1.65;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
    }

    .stat-card {
      padding: 16px;
      border-radius: 18px;
      background: #fff;
      border: 1px solid var(--border);
      box-shadow: var(--shadow-soft);
    }

    .stat-label {
      display: block;
      color: var(--muted);
      font-size: 0.88rem;
      margin-bottom: 6px;
    }

    .stat-value {
      font-size: 1.12rem;
      font-weight: 700;
    }

    .button-row,
    .dialog-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
    }

    .button {
      border: 0;
      border-radius: 14px;
      padding: 13px 18px;
      font-weight: 700;
      cursor: pointer;
      transition: transform 140ms ease, box-shadow 140ms ease, background 140ms ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button:focus-visible {
      outline: 3px solid rgba(37, 99, 235, 0.24);
      outline-offset: 3px;
    }

    .button-secondary {
      background: #eef4ff;
      color: var(--accent);
      box-shadow: inset 0 0 0 1px rgba(37, 99, 235, 0.08);
    }

    .button-secondary:hover {
      background: #e6efff;
    }

    .button-danger {
      background: var(--danger);
      color: #fff;
      box-shadow: 0 12px 24px rgba(225, 29, 72, 0.24);
    }

    .button-danger:hover {
      background: var(--danger-deep);
    }

    .button-ghost {
      background: #fff;
      color: var(--text);
      box-shadow: inset 0 0 0 1px var(--border);
    }

    .helper-note {
      padding: 16px 18px;
      border-radius: 18px;
      background: linear-gradient(135deg, rgba(37, 99, 235, 0.09), rgba(96, 165, 250, 0.13));
      border: 1px solid rgba(37, 99, 235, 0.12);
    }

    .helper-note strong {
      display: block;
      margin-bottom: 6px;
    }

    .dialog-backdrop {
      position: fixed;
      inset: 0;
      display: none;
      align-items: center;
      justify-content: center;
      padding: 20px;
      background: rgba(15, 23, 42, 0.56);
      backdrop-filter: blur(8px);
      -webkit-backdrop-filter: blur(8px);
    }

    .dialog-backdrop.is-open {
      display: flex;
    }

    .dialog {
      width: min(100%, 460px);
      padding: 24px;
      border-radius: 24px;
      background: rgba(255, 255, 255, 0.96);
      border: 1px solid rgba(255, 255, 255, 0.85);
      box-shadow: var(--shadow);
      transform: translateY(12px) scale(0.98);
      opacity: 0;
      transition: transform 180ms ease, opacity 180ms ease;
    }

    .dialog-backdrop.is-open .dialog {
      transform: translateY(0) scale(1);
      opacity: 1;
    }

    .dialog-icon {
      width: 52px;
      height: 52px;
      display: grid;
      place-items: center;
      border-radius: 16px;
      background: var(--danger-soft);
      color: var(--danger);
      margin-bottom: 18px;
      font-size: 1.4rem;
    }

    .dialog-copy {
      display: grid;
      gap: 10px;
      margin-bottom: 22px;
    }

    .dialog-actions {
      justify-content: flex-end;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 900px) {
      .preview-layout {
        grid-template-columns: 1fr;
      }

      .preview-card {
        min-height: auto;
      }
    }

    @media (max-width: 640px) {
      .card-footer {
        flex-direction: column;
        align-items: stretch;
      }

      .button-row,
      .dialog-actions {
        flex-direction: column-reverse;
      }

      .button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    const state = {
      isDialogOpen: false
    };

    function Button({ className = "", label, type = "button", dataAction = "" }) {
      return `
        <button type="${type}" class="button ${className}" ${dataAction ? `data-action="${dataAction}"` : ""}>
          ${label}
        </button>
      `;
    }

    function ConfirmDeleteModal({ open }) {
      return `
        <div class="dialog-backdrop ${open ? "is-open" : ""}" ${open ? "" : "hidden"} data-backdrop>
          <div
            class="dialog"
            role="dialog"
            aria-modal="true"
            aria-labelledby="delete-dialog-title"
            aria-describedby="delete-dialog-description"
          >
            <div class="dialog-icon" aria-hidden="true">!</div>
            <div class="dialog-copy">
              <h2 id="delete-dialog-title">Delete this image?</h2>
              <p id="delete-dialog-description">
                This will permanently remove the image from your library. You can’t undo this action after deleting it.
              </p>
            </div>
            <div class="dialog-actions">
              ${Button({ className: "button-ghost", label: "Cancel", dataAction: "close-dialog" })}
              ${Button({ className: "button-danger", label: "Delete image", dataAction: "confirm-delete" })}
            </div>
          </div>
        </div>
      `;
    }

    function ImagePreviewCard() {
      return `
        <section class="preview-card glass-card" aria-label="Image preview">
          <div class="image-stage">
            <div class="stage-chip">Image preview</div>
            <div class="image-meta">
              <h1>Golden hour ridge</h1>
              <p>
                A high-resolution landscape capture prepared for campaign publishing, collaboration reviews, and final library approval.
              </p>
            </div>
          </div>

          <div class="card-footer">
            <div class="asset-details">
              <strong>golden-hour-ridge.jpg</strong>
              <div class="meta-row">
                <span class="meta-pill">5472 x 3648</span>
                <span class="meta-pill">12.8 MB</span>
                <span class="meta-pill">Updated 3 hours ago</span>
              </div>
            </div>

            <div class="button-row">
              ${Button({ className: "button-secondary", label: "Download" })}
              ${Button({ className: "button-danger trigger", label: "Delete image", dataAction: "open-dialog" })}
            </div>
          </div>
        </section>
      `;
    }

    function DetailsPanel() {
      return `
        <aside class="sidebar glass-card" aria-label="Image details">
          <div>
            <h2>Library details</h2>
            <p>Review core asset metadata before publishing or removing the image from your shared workspace.</p>
          </div>

          <div class="stats-grid">
            <div class="stat-card">
              <span class="stat-label">Status</span>
              <span class="stat-value">Ready to publish</span>
            </div>
            <div class="stat-card">
              <span class="stat-label">Color profile</span>
              <span class="stat-value">Adobe RGB</span>
            </div>
            <div class="stat-card">
              <span class="stat-label">Used in</span>
              <span class="stat-value">4 collections</span>
            </div>
            <div class="stat-card">
              <span class="stat-label">Owner</span>
              <span class="stat-value">Brand Studio</span>
            </div>
          </div>

          <div class="helper-note">
            <strong>Delete protection</strong>
            Removing this image prompts for confirmation first, preventing accidental library changes.
          </div>
        </aside>
      `;
    }

    function App() {
      return `
        <main class="page-shell">
          <div class="preview-layout">
            ${ImagePreviewCard()}
            ${DetailsPanel()}
          </div>
          ${ConfirmDeleteModal({ open: state.isDialogOpen })}
          <p class="sr-only" aria-live="polite">${state.isDialogOpen ? "Delete confirmation dialog opened." : "Delete confirmation dialog closed."}</p>
        </main>
      `;
    }

    function render() {
      document.getElementById("app").innerHTML = App();
    }

    document.addEventListener("click", (event) => {
      const actionTarget = event.target.closest("[data-action]");
      const backdrop = event.target.closest("[data-backdrop]");
      const dialog = event.target.closest(".dialog");

      if (actionTarget) {
        const action = actionTarget.dataset.action;

        if (action === "open-dialog") {
          state.isDialogOpen = true;
          render();
          return;
        }

        if (action === "close-dialog" || action === "confirm-delete") {
          state.isDialogOpen = false;
          render();
          return;
        }
      }

      if (backdrop && !dialog) {
        state.isDialogOpen = false;
        render();
      }
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && state.isDialogOpen) {
        state.isDialogOpen = false;
        render();
      }
    });

    render();
  </script>
</body>
</html>
